function answerCard(a){const card=el('article',{class:'message answer'},el('div',{class:'signal-meta'},tag('Intelligence brief'),el('span',{text:'Snapshot checked '+time(a.checkedAt)})),el('p',{text:a.summary}));const refs=item=>item.sourceIds.map(id=>{const s=a.sources.find(s=>s.id===id);return s?el('a',{class:'source-ref',href:trusted(s.url)?s.url:'#',target:'_blank',rel:'noopener noreferrer',text:'['+id+']','aria-label':id+': '+s.name}):null;});for(const [key,label] of [['findings','Source-backed observations'],['actions','Strategic hypotheses & next steps']])if(a[key]?.length)card.append(el('div',{class:'answer-section'},el('h3',{text:label}),el('ul',{},...a[key].map(item=>el('li',{},item.text,...refs(item))))));if(a.gaps?.length)card.append(el('div',{class:'answer-section'},el('h3',{text:'Evidence gaps'}),el('ul',{},...a.gaps.map(t=>el('li',{text:t})))));if(a.sources?.length)card.append(el('details',{},el('summary',{text:'Review '+a.sources.length+' underlying source records'}),el('div',{class:'source-list'},...a.sources.map(s=>el('div',{},link('['+s.id+'] '+s.name+' ↗',s.url),el('small',{text:' · '+s.kind}))))));if(a.liveNote)card.append(el('p',{class:'note',text:a.liveNote+(a.liveCheckedAt?' Checked '+time(a.liveCheckedAt)+'.':'')}));return card;}
function coverage(m){m.append(head('Know what your intelligence covers.','Source scope, freshness and limitations are part of every commercial judgement.'));const age=Date.now()-new Date(overview.lastRunAt);m.append(el('div',{class:'wide-notice',text:`Monitoring is scheduled daily at 08:17 IST (02:47 UTC). Scheduled checks can be delayed. Last recorded run: ${time(overview.lastRunAt)}. ${age>36*3600000?'The snapshot is older than 36 hours. Treat it as stale.':'The current snapshot is within the 36-hour freshness window.'} A successful check means a source returned records, not that every global development was captured.`}));m.append(el('div',{class:'source-grid'},...overview.sourceChecks.map(s=>el('article',{class:'card source-card'},el('div',{class:'card-head'},el('h2',{text:s.name}),tag(s.status==='current'?'Checked':'Refresh unavailable',s.status==='current'?'':'amber')),el('p',{text:s.coverage}),el('div',{class:'source-row'},el('span',{text:fmt(s.records||0)+' records'}),el('span',{text:s.truncated?'Bounded snapshot':'Source collection'})),el('p',{class:'note',text:'Last successful check: '+time(s.lastSuccessAt)}),s.detail?el('p',{class:'note',text:'The latest check did not complete. Previously collected records may remain visible.'}):null,link('Open official source ↗',s.url)))));
 m.append(el('section',{class:'card spaced'},sectionHead('How to use this workspace responsibly'),...['Scope: all therapy areas, with US and EU medicine sources, global trial registry records, selected company announcements, and US pricing benchmarks. It is not an exhaustive list of all products, trials or markets.','Dates: a source record update, regulatory decision, observation date and commercial launch are different events. The app labels each according to available evidence.','Observed changes: comparisons start from the initial collection on '+date(overview.baselineAt)+'. Newly observed records are not automatically new products. A source falling out of a bounded feed is not treated as a product withdrawal.','Pricing: US NADAC values describe acquisition benchmarks per unit. They do not support cross-country net-price comparisons or total treatment costs without additional evidence.','Opportunities: rule-selected research hypotheses need validation of demand, competition, access, differentiation and economics. The app does not calculate market size or expected revenue.','Your followed products stay in this browser. This workspace does not send email alerts. Daily monitoring updates the shared evidence snapshot.'].map(t=>el('p',{class:'muted',text:t}))));}
function exportBrief(){if(!overview)return;let text=`MARKETSIGNAL | GLOBAL PHARMA INTELLIGENCE\n\nEvidence snapshot: ${time(overview.lastRunAt)}\nScope: ${overview.coverage.note}\n\n`;if(lastBrief){const {question,answer:a}=lastBrief;text+=`RESEARCH QUESTION\n${question}\n\n${a.summary}\n\n`;for(const [key,title] of [['findings','SOURCE-BACKED OBSERVATIONS'],['actions','HYPOTHESES AND NEXT STEPS']])text+=title+'\n'+a[key].map(x=>'- '+x.text+' ['+x.sourceIds.join(', ')+']').join('\n')+'\n\n';text+='EVIDENCE GAPS\n'+a.gaps.map(x=>'- '+x).join('\n')+'\n\nSOURCES\n'+a.sources.map(s=>`[${s.id}] ${s.name}\n${s.url}`).join('\n\n');}else{text+='COVERAGE\n'+Object.entries(overview.stats).map(([k,v])=>`${k}: ${fmt(v)}`).join('\n')+'\n\nRECENT SIGNALS\n'+overview.events.slice(0,8).map(e=>`${e.title}\n${date(e.date)} | ${e.region}\n${e.fact}\n${e.url}`).join('\n\n');}text+='\n\nPublic-source business research. Verify source records, local commercial availability and economic assumptions before acting.\n';const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=el('a',{href:url,download:'MarketSignal-intelligence-brief.txt'});a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Your intelligence brief is ready.');}
